                {showRunnerBoxes ? `Runners ${runnerBoxes.length}` : 'Active Task'}
              </span>
              {engineState?.activeProjectName && (
                <span className="text-[9px] text-text-muted font-mono truncate hidden sm:inline">
                  [{engineState.activeProjectName}]
                </span>
              )}
