              >
                {visibleRunnerBoxes.map((box) => {
                  const health = runnerBoxHealth(box.lastSeenAt, nowMs);
                  const stateLabel = box.idle
                    ? 'idle, no task assigned'
                    : `${box.paused ? 'paused' : 'active'}, task: ${box.taskName}, stage: ${box.stageName}`;
