              </div>
            ) : (
              <InfoTooltip
                title="Inspect Active Task"
                description="Click to open the Slide-Over Inspector for live logs, markdown goals, and reports."
                behindTheScenes="Loads task details and disk-persisted reports from docs/tasks/<id>/"
