export function resolveDefaultGitRemote(slug, { name } = {}) {
	const template = (process.env.KAINBAIN_GIT_REMOTE_TEMPLATE || "").trim();
	if (!template) return null;
	const user = (process.env.USER || process.env.USERNAME || "").trim();
	return template
		.split("${SLUG}")
		.join(slug || "")
		.split("${NAME}")
		.join(name || slug || "")
		.split("${USER}")
